def parse_version(s: str) -> tuple[int]:
    """poor man's version comparison"""

    parts = s.split('.')
    current_version = int(parts[0])
    version_sequence = []

    if len(parts) == 1:
        return (current_version, )

    for part in parts[1:]:
        part = part.strip()
        try:
            version_sequence.append(int(part))
        except ValueError:
            continue

    return (current_version,) + tuple(version_sequence)

