def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if number == 0:
        return "0" * (padding or 1)
    else:
        digits = []
        while number:
            digit = number % len(alphabet)
            digits.append(alphabet[digit])
            number //= len(alphabet)
        return ''.join(digits[::-1]) + ('0' * (((padding or 1) - len(digits)) % (padding or 1)))

