def _resolve_string(matcher: str) -> Optional[str]:
    try:
        return os.environ[matcher]
    except KeyError:
        if matcher.endswith("="):
            try:
                return int(matcher[:-1])  # Assuming '=' separates name and value
            except ValueError:
                pass
        if '=' in matcher:  # Trying to split by '=' and getting value
            name, value = matcher.split('=', 1)
            value = value.strip()
            os.environ[name] = value  # Making sure value is in the environment
        else:
            raise EnvironmentError(f"Could not resolve the value for variable '{matcher}'.")

