def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    if dumper is None:
        dumper = yaml.dumper.SafeDumper
    if isinstance(obj, str):
        return obj
    elif isinstance(obj, dict):
        return yaml.safe_dump(obj, allow_unicode=True, Dumper=dumper)
