def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    tags_set = set()
    new_text = ''
    in_code_block = False

    for line_number, line in enumerate(text.split('\n')):
        if '<pre>' in line:
            in_code_block = True
        elif '</pre>' in line:
            in_code_block = False
        elif in_code_block:
            new_text += line + '\n'
            continue

        # find all tags in this line
        for match in re.finditer(r'\b\w+\b', line.upper()):
            tag = match.group(0)
            tags_set.add(tag)

            # optionally replace the tag
            if replacer:
                new_text += replacer(tag) + '\n'
            else:
                new_text += tag + '\n'

    return tags_set, new_text

