def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""

    _PATH_RE = re.compile(r'\b(http|https|ftp):\/\/[^ ]*\b|\b[\w-]+\.\w+\b')

    def to_url(m):
        scheme = 'http' if m.groups()[0] is None else m.groups()[0].lower()
        host = m.group(0)
        if host.startswith('/'):
            path = host
        elif host.startswith('..'):
            path = ''
        else:
            path = host.split(':')[0].lstrip('/')
        url = f"{scheme}://{host}:{port}{path.lstrip('/')}"
        return url

    def maybe_add_link(url, text):
        return f'<a href="{url}" rel="noopener noreferrer">{text}</a>' if url else text

    return _PATH_RE.sub(lambda m: maybe_add_link(to_url(m), m.group(0)), text)

