def validate_from_content(cls, spec_content):
        if not spec_content:
            raise ValueError("spec_content cannot be None")
        try:
            spec = yaml.safe_load(spec_content)
        except yaml.YAMLError as e:
            raise IRValidatorException(f"Invalid spec content: {e}")

        if not isinstance(spec, dict):
            raise IRValidatorException("Spec content must be a dictionary")

        required_fields = cls.get_required_fields(spec)
        missing_fields = [field for field in required_fields if field not in spec]

        if missing_fields:
            raise IRValidatorException(f"Missing required fields: {missing_fields}")

        return spec

    @classmethod
    def get_required_fields(cls, spec):
        required_fields = []
        for key, value in spec.items():
            if cls.is_required(value):
                required_fields.append(key)
        return required_fields

    @staticmethod
    def is_required(value):
        if isinstance(value, dict):
            return all(cls.is_required(field) for field in value)
        return value is not None and value != "__undefined__"

