def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    # Helper method to check if a path exists
    def path_exists(path):
        import os
        return os.path.exists(path)

    # Helper method to read the content of a file
    def read_file_content(file_path):
        with open(file_path, 'r') as file:
            return file.read()

    # Helper method to process the include directive
    def process_includeDirective(node, path):
        if node.name == 'include':
            included_path = node.value
            if path_exists(included_path):
                content = read_file_content(included_path)
                node.parent.insert(content, node)
            else:
                raise FileNotFoundError(f"Included file '{included_path}' not found")

    # Recursively process all nodes in the dictionary
    def recursive_process_dict(node):
        if node.type == 'dictionary':
            for key, value in iteritems(node.value):
                recursive_process_dict(value)
                if isinstance(value, dict) and 'include' in value:
                    process_includeDirective(value, node.path)
        elif node.type == 'section':
            for key, value in iteritems(node.value):
                recursive_process_dict(value)
                if isinstance(value, dict) and 'include' in value:
                    process_includeDirective(value, node.path)

    # Start processing the dictionary at the top level
    recursive_process_dict(parser_dict)

