def validate_min_max_args(self, args):
    """
    Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    if 'min_' not in args or 'max_' not in args:
        raise ValueError("Minimum and maximum values must be provided")
    if args['min'] > args['max']:
        raise ValueError("Minimum value must be less than or equal to maximum value")
    for key, value in args.items():
        if key in ('min', 'max'):
            continue
        if not isinstance(value, (int, float)):
            raise TypeError("All arguments must be numbers")
        if value < args['min'] or value > args['max']:
            raise ValueError(f"{key} value is out of range")
    return args

